def transform(grid):
    g = np.array(grid)
    bg = background(g)
    out = g.copy()
    objs = objects(g, bg=bg)
    # stage 1: objects of exactly 6 cells become colour 2
    for o in objs:
        if o["size"] == 6:
            for (y, x) in o["cells"]:
                out[y, x] = 2
    emit(out, "Recolour every object made of exactly 6 cells to 2 (red).")
    # stage 2: all other objects become colour 1
    for o in objs:
        if o["size"] != 6:
            for (y, x) in o["cells"]:
                out[y, x] = 1
    emit(out, "Recolour all remaining objects (any size other than 6) to 1 (blue).")
    return out
